"""DHS-8 self-reports beyond Nepal: module inventory, published 15-19 prevalence, pooled IPUMS DHS estimates (Nepal, Mozambique, Bangladesh), literature."""
def build(ctx):
    pd, np, go = ctx.pd, ctx.np, ctx.go
    inv = pd.read_csv(ctx.T/"dhs8_module_inventory.csv"); pub = pd.read_csv(ctx.T/"dhs8_prevalence_published.csv"); E = pd.read_csv(ctx.T/"dhs8_estimates.csv")
    M = pd.read_csv(ctx.T/"dhs8_means.csv"); C = pd.read_csv(ctx.T/"dhs8_published_vs_microdata.csv"); G = pd.read_csv(ctx.T/"dhs8_diag.csv"); lit = pd.read_csv(ctx.T/"dhs8_literature.csv")
    f1 = lambda v: "" if pd.isna(v) else f"{v:.1f}"; fn = lambda v: "" if pd.isna(v) else f"{int(round(v)):,}"
    # ---------- inventory ----------
    mod = inv[inv.module != "none"].copy(); none_n = int((inv.module == "none").sum()); order = {"PHQ-9 + GAD-7": 0, "PHQ-9 only": 1, "diagnosis only": 2}
    mod["o"] = mod.module.map(order); mod = mod.sort_values(["o", "fieldwork_year"])
    inv_rows = [[f"{r.country} {r.fieldwork_year}", r.module, r.women_universe, r.men_asked, r.internet_items, r.smartphone_item, r.ipums_dhs_status] for r in mod.itertuples()]
    n_phq = int((inv.module == "PHQ-9 + GAD-7").sum()); n_phqonly = int((inv.module == "PHQ-9 only").sum()); n_diag = int((inv.module == "diagnosis only").sum()); n_reports = len(inv)
    # ---------- published prevalence, 15-19 and 20-24, by sex ----------
    p = pub[pub.group.isin(["15-19"]) & pub.phq9_ge10.notna()].copy(); p["label"] = p.country + " " + p.year.astype(str)
    anx_label = lambda r: f"{f1(r.anxiety_report_pct)} ({r.anxiety_report_def})" if pd.notna(r.anxiety_report_pct) else "not asked"
    prev_rows = [[r.label, r.sex, r.group, fn(r.n_weighted), f1(r.phq9_ge10), f1(r.phq9_ge5), anx_label(r), f1(r.gad7_ge10) if pd.notna(r.gad7_ge10) else "", f1(r.told_dep)] for r in p.sort_values(["country", "sex", "group"]).itertuples()]
    dg = pub[pub.group.eq("15-19") & pub.told_dep_or_anx.notna()].copy(); dg["label"] = dg.country + " " + dg.year.astype(str)
    diag_rows = [[r.label, r.sex, fn(r.n_weighted), f1(r.told_dep_or_anx)] for r in dg.sort_values(["country", "sex"]).itertuples()]
    # chart 1: PHQ-9 >= 10 at 15-19 and 20-24 by survey and sex
    q = p[p.group == "15-19"].sort_values(["country", "sex"]); fig = go.Figure()
    for sex, col in [("women", ctx.GIRL), ("men", ctx.BOY)]:
        s = q[q.sex == sex]; fig.add_bar(name=f"{sex}, PHQ-9 ≥ 10", x=s.label, y=s.phq9_ge10, marker_color=col, text=[f1(v) for v in s.phq9_ge10], textposition="outside")
    fig.update_layout(barmode="group", yaxis_title="% of 15–19-year-olds", xaxis_title="", yaxis_range=[0, float(q.phq9_ge10.max()) * 1.2]); ctx.figs["dhs8_prev"] = ctx.base(fig, h=360)
    # ---------- microdata estimates ----------
    def row(sample, ages, x, y, fe="cluster FE", subset="all"):
        r = E[(E["sample"] == sample) & (E.ages == ages) & (E.exposure == x) & (E.outcome == y) & (E.fe == fe) & (E.subset == subset)]
        return r.iloc[0] if len(r) else None
    def cell(sample, ages, x, y, subset="all"):
        r = row(sample, ages, x, y, "survey x cluster FE" if sample == "pooled" else "cluster FE", subset); return ctx.fmt(r.coef, r.se) if r is not None else "—"
    XL = {"net_daily": "almost-daily internet use", "net_weekly": "weekly+ internet use", "smart": "owns a smartphone", "ownphone": "owns a phone"}
    surveys = [("np2022ir", "Nepal 2022"), ("bd2022ir", "Bangladesh 2022"), ("mz2022ir", "Mozambique 2022-23"), ("pooled", "Pooled")]
    est_rows = []
    for x in ["net_daily", "net_weekly", "smart", "ownphone"]:
        for ages in ["15-19", "20-24", "25-49"]:
            r = row("pooled", ages, x, "phq10", "survey x cluster FE"); n = fn(r.n) if r is not None else ""
            est_rows.append([XL[x] if ages == "15-19" else "", ages] + [cell(s, ages, x, "phq10") for s, _ in surveys] + [cell(s, ages, x, "gad10") for s, _ in surveys] + [n])
    # pooled key numbers for the prose
    pd15 = row("pooled", "15-19", "net_daily", "phq10", "survey x cluster FE"); gd15 = row("pooled", "15-19", "net_daily", "gad10", "survey x cluster FE")
    ps15 = row("pooled", "15-19", "smart", "phq10", "survey x cluster FE"); gs15 = row("pooled", "15-19", "smart", "gad10", "survey x cluster FE")
    pd25 = row("pooled", "25-49", "net_daily", "phq10", "survey x cluster FE"); gd25 = row("pooled", "25-49", "net_daily", "gad10", "survey x cluster FE")
    ps25 = row("pooled", "25-49", "smart", "phq10", "survey x cluster FE"); gs25 = row("pooled", "25-49", "smart", "gad10", "survey x cluster FE")
    bdp = row("bd2022ir", "15-19", "net_daily", "phq10"); bdg = row("bd2022ir", "15-19", "net_daily", "gad10"); npp = row("np2022ir", "15-19", "net_daily", "phq10"); npg = row("np2022ir", "15-19", "net_daily", "gad10")
    mzs_p = row("mz2022ir", "15-19", "smart", "phq10"); mzs_g = row("mz2022ir", "15-19", "smart", "gad10")
    urb = {k: row("pooled", "15-19", "net_daily", k, "survey x cluster FE", "urban") for k in ["phq10", "gad10"]}; rur = {k: row("pooled", "15-19", "net_daily", k, "survey x cluster FE", "rural") for k in ["phq10", "gad10"]}
    urb_s = {k: row("pooled", "15-19", "smart", k, "survey x cluster FE", "urban") for k in ["phq10", "gad10"]}; rur_s = {k: row("pooled", "15-19", "smart", k, "survey x cluster FE", "rural") for k in ["phq10", "gad10"]}
    # chart 2: coefficient plot, daily internet and smartphone on PHQ-9 >= 10 / GAD-7 >= 10 by age group, per survey and pooled
    sub = E[(E.subset == "all") & (E.fe.isin(["cluster FE", "survey x cluster FE"])) & E.exposure.isin(["net_daily", "smart"]) & E.outcome.isin(["phq10", "gad10"])].copy()
    fig2 = ctx.make_subplots(rows=1, cols=2, subplot_titles=("Almost-daily internet use", "Owns a smartphone"), shared_yaxes=True)
    cols = {"Nepal 2022": ctx.PAL[0], "Bangladesh 2022": ctx.PAL[3], "Mozambique 2022-23": ctx.PAL[2]}; shown = set()
    for ci, x in enumerate(["net_daily", "smart"], start=1):
        for yi, (y, sym) in enumerate([("phq10", "circle"), ("gad10", "diamond")]):
            for si, (s, lab) in enumerate(surveys):
                d = sub[(sub.exposure == x) & (sub.outcome == y) & (sub["sample"] == s)].sort_values("ages")
                if not len(d): continue
                off = (si - 1.5) * 0.17 + (yi - 0.5) * 0.07; xs = [["15-19", "20-24", "25-49"].index(a) + off for a in d.ages]
                fig2.add_scatter(x=xs, y=d.coef, error_y=dict(type="data", array=1.96*d.se, thickness=1), mode="markers", marker=dict(symbol=sym, size=9 if s == "pooled" else 7, color=("#222" if s == "pooled" else cols[lab])),
                                 name=f"{lab}, {'PHQ-9 ≥ 10' if y == 'phq10' else 'GAD-7 ≥ 10'}", legendgroup=f"{lab}{y}", showlegend=(f"{lab}{y}" not in shown), row=1, col=ci); shown.add(f"{lab}{y}")
        fig2.add_hline(y=0, line_color=ctx.MUTED, line_width=1, row=1, col=ci)
        fig2.update_xaxes(tickvals=[0, 1, 2], ticktext=["15–19", "20–24", "25–49"], row=1, col=ci)
    fig2.update_yaxes(title_text="pp difference, users vs non-users (95% CI)", row=1, col=1); ctx.figs["dhs8_coef"] = ctx.base(fig2, h=420, hovermode="closest")
    # means context
    m15 = M[M.ages == "15-19"].set_index("sample")
    # ---------- diagnosis set ----------
    ke_s = G[(G["sample"] == "ke2022ir") & (G.ages == "15-19") & (G.exposure == "smart")].iloc[0]; mgw = G[(G["sample"] == "mg2021ir") & (G.ages == "15-19")].iloc[0]; mgm = G[(G["sample"] == "mg2021mr") & (G.ages == "15-19") & (G.exposure == "net_daily")].iloc[0]
    # ---------- literature ----------
    lit_rows = [[r.survey, f'<a href="{r.doi_or_url}">{r.citation.split("(")[0].strip().rstrip(",")}</a> ({r.citation.split("(")[1].split(")")[0]})', r.instruments_cutoffs, r.prevalence, r.screen_or_media_exposure, r.verification] for r in lit.itertuples()]
    html = f"""<h3 id="dhs8">DHS-8 self-reports beyond Nepal</h3>
<p>The Phase 1 report used one survey with adolescent self-reports of depression and anxiety outside the school-based GSHS: the Nepal 2022 DHS. The DHS Program's optional DHS-8 mental-health module administers the GAD-7 and PHQ-9 to women (and, in some surveys, men) aged 15–49 together with the standard internet-frequency and smartphone items, so every additional survey that fields it is a second self-report test of the MICS caregiver null. We read the final reports of all {n_reports} DHS surveys with fieldwork from 2019 released by October 2026, checked the DHS-8 recode data dictionaries, and inventoried the IPUMS DHS integrated files. {n_phq} surveys carry both scales (Nepal 2022, Mozambique 2022–23, Bangladesh 2022, Zambia 2024), {n_phqonly} carries the PHQ-9 only (Lesotho 2023–24), {n_diag} ask only whether a provider ever diagnosed depression or anxiety (Kenya 2022, Madagascar 2021, Mali 2023–24, DR Congo 2023–24), and the remaining {none_n}, including the Jordan 2023 and Cambodia 2021–22 surveys named in the Phase 2 plan, have no mental-health chapter and no RECMTH file in their recode. The DHS Program API and STATcompiler publish no indicator from the module, so the published figures below were parsed from the final-report tables.</p>
{ctx.table(["Survey", "Module", "Women asked", "Men asked", "Internet frequency item", "Smartphone item", "IPUMS DHS file (October 2026)"], inv_rows)}
<p class="caption">DHS surveys with any mental-health content among the {n_reports} final reports released for 2019+ fieldwork. Raw recode names: GAD-7 items mth1–mth7, PHQ-9 items mth8–mth16, provider diagnosis mth19/mth20, scores mth22/mth24 (men: mmth*), internet v171a/v171b, smartphone v169c.</p>
<h4>Published prevalence at ages 15–19</h4>
{ctx.fig_div('dhs8_prev')}
<p class="caption">Percentage of 15–19-year-olds with a PHQ-9 score of 10 or more, from the final-report tables (weighted). Zambia's levels are an order of magnitude below the other surveys; the anxiety columns of the table use each report's own cutoff (GAD-7 ≥ 6 in Nepal, Mozambique and Bangladesh; ≥ 10 in Zambia).</p>
{ctx.table(["Survey", "Sex", "Ages", "n (weighted)", "PHQ-9 ≥ 10 (%)", "PHQ-9 ≥ 5 (%)", "Anxiety, report definition (%)", "GAD-7 ≥ 10 (%)", "Ever told had depression (%)"], prev_rows)}
<p class="caption">Severity tables of the DHS-8 mental-health chapters, ages 15–19 (the 20–24 and 25–49 rows, the residence splits and the source table and page numbers are in <code>results/tables/dhs8_prevalence_published.csv</code>). Bangladesh interviewed ever-married women only, so its 15–19 group is a selected (early-married) population. Lesotho did not field the GAD-7. For the diagnosis-only surveys the share of 15–19-year-olds ever told by a provider that they had depression or anxiety is {"; ".join(f"{r[0]} {r[1]} {r[3]}%" for r in diag_rows)}.</p>
<h4>Microdata: pooled within-cluster estimates</h4>
<p>IPUMS DHS has integrated the women's files of three of the four PHQ-9/GAD-7 surveys (Nepal, Mozambique, Bangladesh; Zambia 2024 and all men's files are not yet available there, and Mozambique's file does not yet carry the internet-frequency item). Weighted means from these files reproduce the final-report tables exactly (for example PHQ-9 ≥ 10 at 15–19: Nepal {f1(C[(C['sample']=='np2022ir')&(C.ages=='15-19')].phq10_microdata.iloc[0])}% vs {f1(C[(C['sample']=='np2022ir')&(C.ages=='15-19')].phq10_report.iloc[0])}% published; Mozambique {f1(C[(C['sample']=='mz2022ir')&(C.ages=='15-19')].phq10_microdata.iloc[0])}% vs {f1(C[(C['sample']=='mz2022ir')&(C.ages=='15-19')].phq10_report.iloc[0])}%; Bangladesh {f1(C[(C['sample']=='bd2022ir')&(C.ages=='15-19')].phq10_microdata.iloc[0])}% vs {f1(C[(C['sample']=='bd2022ir')&(C.ages=='15-19')].phq10_report.iloc[0])}%), and the Nepal rows reproduce the Phase 1 estimates to the third decimal. We then re-ran the Nepal specification on each survey and on the pooled file: women who use the internet almost daily (or weekly or more, or who own a smartphone or any phone) are compared with non-users in the same sampling cluster, with wealth quintile, education level and single-year age controls, survey weights, and standard errors clustered by sampling cluster; the pooled rows add survey-by-cluster fixed effects, let the control effects differ by survey, and normalise each survey's weights to its sample size. Among 15–19-year-old women, {f1(m15.loc['np2022ir','net_daily'])}% in Nepal and {f1(m15.loc['bd2022ir','net_daily'])}% in Bangladesh use the internet almost daily, and {f1(m15.loc['np2022ir','smart'])}%, {f1(m15.loc['bd2022ir','smart'])}% and {f1(m15.loc['mz2022ir','smart'])}% (Nepal, Bangladesh, Mozambique) own a smartphone.</p>
{ctx.fig_div('dhs8_coef')}
<p class="caption">Percentage-point difference in screening positive between users and non-users in the same sampling cluster, by age group; circles PHQ-9 ≥ 10, diamonds GAD-7 ≥ 10; black markers are the pooled survey-by-cluster fixed-effects estimates. The 25–49 group is the falsification contrast.</p>
{ctx.table(["Exposure", "Ages", "Nepal · PHQ-9 ≥ 10", "Bangladesh · PHQ-9", "Mozambique · PHQ-9", "Pooled · PHQ-9", "Nepal · GAD-7 ≥ 10", "Bangladesh · GAD-7", "Mozambique · GAD-7", "Pooled · GAD-7", "Pooled n"], est_rows)}
<p class="caption">Coefficients in percentage points with cluster-robust standard errors in parentheses; women only. Full results, the continuous-score and GAD-7 ≥ 6 outcomes, the urban/rural splits and a precision-weighted average of the per-survey estimates are in <code>results/tables/dhs8_estimates.csv</code>.</p>
<p>Pooling Nepal and Bangladesh, 15–19-year-old women who use the internet almost daily are {ctx.fmt(pd15.coef, pd15.se)} pp more likely to screen positive for depression and {ctx.fmt(gd15.coef, gd15.se)} pp more likely to screen positive for anxiety than non-users in the same cluster (n = {fn(pd15.n)}). The Nepal estimates ({ctx.fmt(npp.coef, npp.se)} and {ctx.fmt(npg.coef, npg.se)}) are not reproduced in Bangladesh ({ctx.fmt(bdp.coef, bdp.se)} and {ctx.fmt(bdg.coef, bdg.se)}), whose 15–19-year-olds are all ever-married. Smartphone ownership pooled across the three surveys gives {ctx.fmt(ps15.coef, ps15.se)} pp on depression and {ctx.fmt(gs15.coef, gs15.se)} pp on anxiety (n = {fn(ps15.n)}); Mozambique's own estimates are {ctx.fmt(mzs_p.coef, mzs_p.se)} and {ctx.fmt(mzs_g.coef, mzs_g.se)}. At ages 25–49 the pooled coefficients are {ctx.fmt(pd25.coef, pd25.se)} and {ctx.fmt(gd25.coef, gd25.se)} for daily internet use and {ctx.fmt(ps25.coef, ps25.se)} and {ctx.fmt(gs25.coef, gs25.se)} for smartphone ownership: the positive point estimates are confined to the youngest group, as in Nepal alone, but none is distinguishable from zero. Splitting the 15–19 pooled sample by residence gives {ctx.fmt(urb['phq10'].coef, urb['phq10'].se)} (depression) and {ctx.fmt(urb['gad10'].coef, urb['gad10'].se)} (anxiety) for daily internet use in urban clusters against {ctx.fmt(rur['phq10'].coef, rur['phq10'].se)} and {ctx.fmt(rur['gad10'].coef, rur['gad10'].se)} in rural clusters, and {ctx.fmt(urb_s['phq10'].coef, urb_s['phq10'].se)} / {ctx.fmt(urb_s['gad10'].coef, urb_s['gad10'].se)} against {ctx.fmt(rur_s['phq10'].coef, rur_s['phq10'].se)} / {ctx.fmt(rur_s['gad10'].coef, rur_s['gad10'].se)} for smartphone ownership. In the diagnosis-only surveys, owning a smartphone is unrelated to an ever-diagnosed depression among Kenyan women aged 15–19 ({ctx.fmt(ke_s.coef, ke_s.se)} pp, n = {fn(ke_s.n)}, base rate {f1(ke_s.mean_y)}%), and in Madagascar ever having used the internet (women, {ctx.fmt(mgw.coef, mgw.se)}) or using it daily (men, {ctx.fmt(mgm.coef, mgm.se)}) is likewise unrelated to a diagnosis that fewer than 1% of 15–19-year-olds report.</p>
<h4>Published analyses of the module</h4>
{ctx.table(["Survey", "Study", "Instruments", "Prevalence", "Screen / media exposure", "Verification"], lit_rows)}
<p class="caption">Peer-reviewed analyses of the DHS-8 mental-health modules located by October 2026. None models adolescents separately or uses the internet-frequency or smartphone items as the exposure of interest; the two that include internet use as a covariate point in opposite directions (Mozambique: higher odds of anxiety; Bangladesh: lower odds of both, unverified).</p>
<div class="note"><strong>Assessment.</strong> Adding Mozambique and Bangladesh to Nepal triples the self-report sample but does not strengthen the Phase 1 pattern: the pooled within-cluster association between daily internet use and screening positive at ages 15–19 is {ctx.fmt(pd15.coef, pd15.se)} pp for depression and {ctx.fmt(gd15.coef, gd15.se)} pp for anxiety, smaller than Nepal's own estimates and not significant, and smartphone ownership across three surveys gives {ctx.fmt(ps15.coef, ps15.se)} and {ctx.fmt(gs15.coef, gs15.se)} pp. The direction is consistent with H1 (positive at 15–19, zero or negative at 25–49, as in the GSHS self-reports and unlike the MICS caregiver reports), but the magnitudes are a third to a half of the GSHS phone-hours gradients and the intervals include zero, so these cross-sections neither confirm nor rule out a self-report-specific effect of the size seen in GSHS. They say nothing about H2 or H3 (no school items) and do not bear on H0. Three limits apply: the exposures are current use rather than exogenous rollout; Bangladesh's 15–19-year-olds are ever-married women, a group selected on early marriage; and the men's files, the Zambia 2024 survey (whose published 15–19 prevalence is an order of magnitude lower than the others), the Lesotho PHQ-9 module and Mozambique's internet items await IPUMS DHS integration or a DHS Program data request.</div>"""
    return {"dhs8": html}
